Here are comprehensive pytest unit tests covering the happy path, edge cases, and error cases:

```python
import pytest


# -----------------------------------------------------------------------------
# Helper functions
# -----------------------------------------------------------------------------
def add_one(x):
    return x + 1


def mul_by_two(x):
    return x * 2


def to_str(x):
    return str(x)


def raise_value_error(x):
    raise ValueError("intentional error")


# -----------------------------------------------------------------------------
# Happy Path
# -----------------------------------------------------------------------------
def test_compose_two_functions_right_to_left():
    """Standard composition: compose(f, g)(x) == f(g(x))"""
    fn = compose(add_one, mul_by_two)
    # mul_by_two(3) -> 6, then add_one(6) -> 7
    assert fn(3) == 7


def test_compose_three_functions():
    fn = compose(to_str, add_one, mul_by_two)
    # mul_by_two(2) -> 4, add_one(4) -> 5, to_str(5) -> "5"
    assert fn(2) == "5"


def test_compose_single_function():
    fn = compose(add_one)
    assert fn(5) == 6


def test_compose_preserves_falsy_return_values():
    """Ensure 0, None, empty strings, etc. are not lost."""
    fn = compose(lambda x: x * 2, lambda _: 0)
    assert fn("ignored") == 0

    fn2 = compose(lambda x: x, lambda _: None)
    assert fn2("ignored") is None

    fn3 = compose(len, lambda _: "")
    assert fn3("ignored") == 0


# -----------------------------------------------------------------------------
# Edge Cases
# -----------------------------------------------------------------------------
def test_compose_no_functions_returns_identity():
    """Calling compose() with no args should return the input unchanged."""
    fn = compose()
    assert fn(42) == 42
    assert fn("hello") == "hello"
    assert fn(None) is None
    assert fn([1, 2, 3]) == [1, 2, 3]


def test_compose_execution_order():
    """Verify the right-most function is applied first."""
    calls = []

    def first(x):
        calls.append("first")
        return x

    def second(x):
        calls.append("second")
        return x

    def third(x):
        calls.append("third")
        return x

    fn = compose(first, second, third)
    fn(1)
    assert calls == ["third", "second", "first"]


def test_compose_returns_distinct_functions():
    """Each call to compose should create a new function object."""
    f1 = compose(add_one)
    f2 = compose(add_one)
    assert f1 is not f2
    assert f1(1) == f2(1) == 2


# -----------------------------------------------------------------------------
# Error Cases
# -----------------------------------------------------------------------------
def test_compose_propagates_exception():
    """Exceptions raised by an inner function should bubble up."""
    fn = compose(add_one, raise_value_error)
    with pytest.raises(ValueError, match="intentional error"):
        fn(10)


def test_compose_type_error_from_mismatched_types():
    """A function producing an output incompatible with the next function."""
    fn = compose(add_one, str)  # str(5) -> "5", then add_one("5") fails
    with pytest.raises(TypeError):
        fn(5)


def test_compose_non_callable_raises_on_execution():
    """Passing a non-callable should fail only when the composed fn runs."""
    fn = compose(add_one, 42)
    with pytest.raises(TypeError):
        fn(0)


def test_composed_function_rejects_extra_positional_args():
    """The returned composed function only accepts a single argument."""
    fn = compose(add_one)
    with pytest.raises(TypeError):
        fn(1, 2)


def test_composed_function_rejects_keyword_args():
    """The returned composed function does not accept keyword arguments."""
    fn = compose(add_one)
    with pytest.raises(TypeError):
        fn(x=5)
```

### Key scenarios covered

| Category | Tests |
|----------|-------|
| **Happy Path** | Two/three function composition, single function, falsy return values |
| **Edge Cases** | Empty `compose()` (identity behavior), strict right-to-left execution order, distinct closure objects |
| **Error Cases** | Exception propagation, type mismatches between composed functions, non-callable items, wrong arity on the outer composed function |
